import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';
import { ProblemSchema } from '../src/lib/problem.ts';

const valid = (i = 0) => ({ email: `user${i}@example.com`, name: `User ${i}` });

describe('users API', () => {
  it('creates, gets, updates, deletes and rejects missing users', async () => {
    const app = createApp();
    const created = await request(app).post('/v1/users').send(valid());
    expect(created.status).toBe(201);
    expect(created.headers.location).toMatch(/^\/v1\/users\//);
    expect(created.body.role).toBe('member');
    expect(created.body.id).toMatch(/^[0-9a-f-]{36}$/);
    const id = created.body.id;
    expect((await request(app).get(`/v1/users/${id}`)).status).toBe(200);
    const patched = await request(app).patch(`/v1/users/${id}`).send({ name: 'Changed' });
    expect(patched.status).toBe(200); expect(patched.body.name).toBe('Changed');
    expect((await request(app).delete(`/v1/users/${id}`)).status).toBe(204);
    for (const method of ['get', 'patch', 'delete'] as const) {
      const res = method === 'patch' ? await request(app).patch(`/v1/users/${id}`).send({ name: 'x' }) : await request(app)[method](`/v1/users/${id}`);
      expect(res.status).toBe(404); expect(res.headers['content-type']).toMatch(/^application\/problem\+json/); ProblemSchema.parse(res.body);
    }
  });
  it('validates body, path, duplicate email, empty patch and malformed JSON', async () => {
    const app = createApp();
    const bad = await request(app).post('/v1/users').send({ email: 'bad', name: '' });
    expect(bad.status).toBe(422); expect(bad.body.detail).toContain('email'); expect(bad.body.detail).toContain('name');
    await request(app).post('/v1/users').send(valid());
    const dup = await request(app).post('/v1/users').send(valid()); expect(dup.status).toBe(409);
    const empty = await request(app).patch('/v1/users/not-a-uuid').send({}); expect(empty.status).toBe(422);
    const malformed = await request(app).post('/v1/users').set('Content-Type','application/json').send('{'); expect(malformed.status).toBe(400);
  });
  it('supports idempotency and duplicate email on patch', async () => {
    const app = createApp(); const key = 'create-key';
    const first = await request(app).post('/v1/users').set('Idempotency-Key', key).send(valid());
    const replay = await request(app).post('/v1/users').set('Idempotency-Key', key).send(valid());
    expect(replay.status).toBe(201); expect(replay.headers['idempotent-replayed']).toBe('true'); expect(replay.body.id).toBe(first.body.id);
    expect((await request(app).post('/v1/users').set('Idempotency-Key', key).send(valid(1))).status).toBe(422);
    const second = await request(app).post('/v1/users').send(valid(1));
    const conflict = await request(app).patch(`/v1/users/${second.body.id}`).send({ email: valid().email }); expect(conflict.status).toBe(409);
  });
  it('cursor paginates every user and validates query', async () => {
    const app = createApp(); for (let i = 0; i < 5; i += 1) await request(app).post('/v1/users').send(valid(i));
    const seen: string[] = []; let cursor: string | undefined;
    do { const res = await request(app).get('/v1/users').query({ limit: 2, cursor }); expect(res.status).toBe(200); seen.push(...res.body.data.map((u: { id: string }) => u.id)); cursor = res.body.nextCursor ?? undefined; } while (cursor);
    expect(new Set(seen).size).toBe(5);
    expect((await request(app).get('/v1/users').query({ limit: 0 })).status).toBe(422);
  });
});

import type { Router, Request, Response, NextFunction } from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, pageSchema, paginate } from '../lib/pagination.ts';

const UserSchema = z.object({ id: z.uuid(), email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.iso.datetime(), updatedAt: z.iso.datetime() });
const CreateSchema = z.object({ email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = z.object({ email: z.email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).strict();
const IdSchema = z.object({ userId: z.uuid() });
type User = z.infer<typeof UserSchema>;

export function registerRoutes(app: Router): void {
  const users = new Map<string, User>();
  const send = (res: Response, body: unknown, status = 200): void => res.status(status).json(UserSchema.parse(body));
  const validate = (schema: z.ZodType, value: unknown): unknown => { const result = schema.safeParse(value); if (!result.success) throw unprocessable(result.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ')); return result.data; };
  const find = (req: Request): User => { const { userId } = validate(IdSchema, req.params) as { userId: string }; const user = users.get(userId); if (!user) throw notFound(`User ${userId} not found`); return user; };
  app.post('/v1/users', idempotency(), (req: Request, res: Response) => { const input = validate(CreateSchema, req.body) as z.infer<typeof CreateSchema>; if ([...users.values()].some((u) => u.email === input.email)) throw conflict('email: already exists'); const now = new Date().toISOString(); const user: User = UserSchema.parse({ ...input, id: randomUUID(), createdAt: now, updatedAt: now }); users.set(user.id, user); res.location(`/v1/users/${user.id}`); send(res, user, 201); });
  app.get('/v1/users', (req: Request, res: Response) => { const query = validate(CursorQuerySchema, req.query) as z.infer<typeof CursorQuerySchema>; res.json(pageSchema(UserSchema).parse(paginate([...users.values()], query, (u) => `${u.createdAt}|${u.id}`))); });
  app.get('/v1/users/:userId', (req: Request, res: Response) => send(res, find(req)));
  app.patch('/v1/users/:userId', idempotency(), (req: Request, res: Response) => { const old = find(req); const patch = validate(PatchSchema, req.body) as z.infer<typeof PatchSchema>; if (Object.keys(patch).length === 0) throw unprocessable('body: empty patch'); if (patch.email !== undefined && [...users.values()].some((u) => u.email === patch.email && u.id !== old.id)) throw conflict('email: already exists'); const updated = UserSchema.parse({ ...old, ...patch, updatedAt: new Date().toISOString() }); users.set(old.id, updated); send(res, updated); });
  app.delete('/v1/users/:userId', (req: Request, res: Response) => { const user = find(req); users.delete(user.id); res.status(204).send(); });
}

