import type { Router, Request, Response, NextFunction } from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, pageSchema, paginate } from '../lib/pagination.ts';

const UserSchema = z.object({ id: z.uuid(), email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.iso.datetime(), updatedAt: z.iso.datetime() });
const CreateSchema = z.object({ email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') }).strict();
const PatchSchema = z.object({ email: z.email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).strict();
const IdSchema = z.object({ userId: z.uuid() });
type User = z.infer<typeof UserSchema>;

export function registerRoutes(app: Router): void {
  const users = new Map<string, User>();
  const handle = (fn: (req: Request, res: Response) => void) => (req: Request, res: Response, next: NextFunction): void => { try { fn(req, res); } catch (error: unknown) { next(error); } };
  const send = (res: Response, body: unknown, status: 200 | 201 = 200): void => { res.status(status).json(UserSchema.parse(body)); };
  const validate = (schema: z.ZodType, value: unknown): unknown => { const result = schema.safeParse(value); if (!result.success) throw unprocessable(result.error.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`).join('; ')); return result.data; };
  const find = (req: Request): User => { const { userId } = validate(IdSchema, req.params) as { userId: string }; const user = users.get(userId); if (!user) throw notFound(`User ${userId} not found`); return user; };
  app.post('/v1/users', idempotency(), handle((req: Request, res: Response) => { const input = validate(CreateSchema, req.body) as z.infer<typeof CreateSchema>; if ([...users.values()].some((u) => u.email === input.email)) throw conflict('email: already exists'); const now = new Date().toISOString(); const user: User = UserSchema.parse({ ...input, id: randomUUID(), createdAt: now, updatedAt: now }); users.set(user.id, user); res.location(`/v1/users/${user.id}`); send(res, user, 201); }));
  app.get('/v1/users', handle((req: Request, res: Response) => { const query = validate(CursorQuerySchema, req.query) as z.infer<typeof CursorQuerySchema>; res.json(pageSchema(UserSchema).parse(paginate([...users.values()], query, (u) => `${u.createdAt}|${u.id}`))); }));
  app.get('/v1/users/:userId', handle((req: Request, res: Response) => send(res, find(req))));
  app.patch('/v1/users/:userId', idempotency(), handle((req: Request, res: Response) => { const old = find(req); const patch = validate(PatchSchema, req.body) as z.infer<typeof PatchSchema>; if (Object.keys(patch).length === 0) throw unprocessable('body: empty patch'); if (patch.email !== undefined && [...users.values()].some((u) => u.email === patch.email && u.id !== old.id)) throw conflict('email: already exists'); const updated = UserSchema.parse({ ...old, ...patch, updatedAt: new Date().toISOString() }); users.set(old.id, updated); send(res, updated); }));
  app.delete('/v1/users/:userId', handle((req: Request, res: Response) => { const user = find(req); users.delete(user.id); res.status(204).send(); }));
}

